P<-'/mnt/BioDisk/wangmingyuan/lung_CD4T_MRE11A_scRNA';O<-file.path(P,'11_reports/human_gap_diagnostics_20261005_v1');R<-file.path(O,'results');H<-file.path(P,'11_reports/human_first_20261004_v1/results');V<-file.path(P,'11_reports/human_alignment_20261005_v1/results');rd<-function(f)read.delim(f,check.names=FALSE);wr<-function(d,n){co<-gzfile(file.path(R,n),'wt');write.table(d,co,sep='\t',quote=FALSE,row.names=FALSE,na='NA');close(co)}
z<-readRDS(file.path(H,'stage2_aggregates.rds'))$receiver[['CD4-IL7R_All']];j<-which(z$sm$cells>=20);ref<-data.frame(gene=rownames(z$logavg),mean_log=rowMeans(z$logavg[,j,drop=FALSE]),pct=rowMeans(z$pct[,j,drop=FALSE]));rownames(ref)<-ref$gene
members<-rd(file.path(R,'independence_program_members.tsv.gz'));target<-members$gene[members$program=='IL7R_nominal_original'&members$type=='target'];bg<-rd(file.path(H,'stage2_background_members.tsv.gz'));bg<-bg$gene[bg$receiver=='CD4-IL7R'&bg$filter=='All'&bg$model=='Source'];alltargets<-rd(file.path(H,'stage2_targetset_members.tsv.gz'))$gene;net<-rd(file.path(V,'existing_TF_edges_complete.tsv.gz'))$target;modules<-rd(file.path(H,'stage1_complete_program_members.tsv'))$gene;ex<-unique(c(alltargets,net,modules,strsplit('IKZF2 STAT1 IL15 TNF CLSTN1 ADAM15 PLAU DSC2 CXCL2 ICAM2 VTN VEGFB GSTP1 RTN4',' ')[[1]]));pool<-setdiff(intersect(bg,ref$gene),ex);pool<-pool[is.finite(ref[pool,'mean_log'])&is.finite(ref[pool,'pct'])];ref$class<-ifelse(grepl('^(RPL|RPS|MRPL|MRPS|MT-)',ref$gene),'RiboMito','Other')
coords<-as.matrix(ref[,c('mean_log','pct')]);coords<-sweep(sweep(coords,2,colMeans(coords[pool,,drop=FALSE]),'-'),2,apply(coords[pool,,drop=FALSE],2,sd),'/');used<-character();matches<-list();missing<-list()
for(g in sort(target)){cand<-setdiff(pool[ref[pool,'class']==ref[g,'class']],used);if(length(cand)<3){missing[[length(missing)+1]]<-data.frame(target=g,status='INSUFFICIENT_SAME_CLASS_UNUSED_CONTROLS');next};dist<-rowSums((sweep(coords[cand,,drop=FALSE],2,coords[g,],'-'))^2);pick<-cand[order(dist,cand)][1:3];used<-c(used,pick);for(k in 1:3)matches[[length(matches)+1]]<-data.frame(target=g,control=pick[k],set=paste0('MatchedControl',k),distance=sqrt(dist[pick[k]]),target_mean=ref[g,'mean_log'],control_mean=ref[pick[k],'mean_log'],target_pct=ref[g,'pct'],control_pct=ref[pick[k],'pct'],class=ref[g,'class'])}
matches<-do.call(rbind,matches);wr(matches,'matched_control_members.tsv.gz');wr(if(length(missing))do.call(rbind,missing) else data.frame(target=character(),status=character()),'matched_control_unmatched_targets.tsv.gz');out<-list();sets<-split(matches$control,matches$set);sets[['MatchedTargetSubset']]<-unique(matches$target)
for(nm in names(sets)){d<-z$sm;d$endpoint<-nm;d$members_n<-length(sets[[nm]]);d$score<-colMeans(z$logavg[sets[[nm]],,drop=FALSE]);out[[length(out)+1]]<-d};wr(do.call(rbind,out),'matched_control_donor_scores.tsv.gz');wr(ref[unique(c(target,pool)),],'matching_reference.tsv.gz');cat('MATCHED_CONTROLS_COMPLETE',length(pool),nrow(matches),'missing',length(missing),'\n')
